mapper.select:
SELECT ID, TGT_CODE, SRC_CODE, ALLOW_SUM, MEMO FROM RSK_VALTBL_ASSET_SUB_MAP_DTL
AND ID = #{id}
order by SRC_CODE

SELECT SUB_CODE, SUB_NAME, SUB_TYPE FROM RSK_VALTBL_SUBJECT
AND SUB_TYPE = #{subType}
ORDER BY SUB_CODE asc

SELECT
count( * )
FROM
RSK_VALTBL_ASSET_SUB_MAP


		AND ID != #{id}


		AND NAME = #{name}
